"""Deterministic build order for a dependency graph. See task.md."""

from __future__ import annotations

import heapq
from collections import deque


class CycleError(ValueError):
    """Raised when the graph contains a cycle.

    `.cycle` names the members of the reported cycle, in depends-on order,
    without repeating the first member at the end.
    """

    def __init__(self, cycle: list[str]) -> None:
        super().__init__("dependency cycle: " + " -> ".join(cycle))
        self.cycle = list(cycle)


def resolve(graph: dict[str, list[str]]) -> list[str]:
    """Return the build order of `graph`, dependencies first."""
    all_nodes: set[str] = set(graph.keys())
    for dep_list in graph.values():
        all_nodes.update(dep_list)

    deps: dict[str, list[str]] = {}
    for node in all_nodes:
        seen: set[str] = set()
        ordered: list[str] = []
        for dep in graph.get(node, []):
            if dep not in seen:
                seen.add(dep)
                ordered.append(dep)
        deps[node] = ordered

    dependents: dict[str, list[str]] = {n: [] for n in all_nodes}
    indegree: dict[str, int] = {}
    for node in all_nodes:
        indegree[node] = len(deps[node])
        for dep in deps[node]:
            dependents[dep].append(node)

    heap = [n for n in all_nodes if indegree[n] == 0]
    heapq.heapify(heap)
    result: list[str] = []
    resolved: set[str] = set()
    while heap:
        node = heapq.heappop(heap)
        resolved.add(node)
        result.append(node)
        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(result) == len(all_nodes):
        return result

    remaining = all_nodes - resolved
    raise CycleError(_find_reported_cycle(remaining, deps))


def _shortest_cycle_length(start: str, remaining: set[str], deps: dict[str, list[str]]) -> int | None:
    """Length of the shortest cycle through `start`, or None if none exists."""
    dist = {start: 0}
    queue = deque([start])
    best: int | None = None
    while queue:
        u = queue.popleft()
        for v in deps.get(u, []):
            if v not in remaining:
                continue
            if v == start:
                cand = dist[u] + 1
                if best is None or cand < best:
                    best = cand
                continue
            if v not in dist:
                dist[v] = dist[u] + 1
                queue.append(v)
    return best


def _cycles_of_length(
    start: str, length: int, remaining: set[str], deps: dict[str, list[str]]
) -> list[list[str]]:
    """All simple cycles of exactly `length` members, starting and ending at `start`."""
    results: list[list[str]] = []
    path = [start]
    on_path = {start}

    def dfs(u: str, depth: int) -> None:
        if depth == length - 1:
            if start in deps.get(u, []):
                results.append(list(path))
            return
        for v in deps.get(u, []):
            if v not in remaining or v in on_path:
                continue
            path.append(v)
            on_path.add(v)
            dfs(v, depth + 1)
            path.pop()
            on_path.discard(v)

    dfs(start, 0)
    return results


def _rotate_to_min(cycle: list[str]) -> list[str]:
    start_index = min(range(len(cycle)), key=lambda i: cycle[i])
    return cycle[start_index:] + cycle[:start_index]


def _find_reported_cycle(remaining: set[str], deps: dict[str, list[str]]) -> list[str]:
    girth: int | None = None
    for node in remaining:
        length = _shortest_cycle_length(node, remaining, deps)
        if length is not None and (girth is None or length < girth):
            girth = length
    assert girth is not None

    best: list[str] | None = None
    for node in remaining:
        for cycle in _cycles_of_length(node, girth, remaining, deps):
            rotated = _rotate_to_min(cycle)
            if best is None or rotated < best:
                best = rotated
    assert best is not None
    return best
